module full_adder1(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    // 使用assign语句描述

    // 和是三个输入的异或
    assign sum = a ^ b ^ cin;

    // 只要三个输入当中有两个是1，就要产生进位，于是这样写
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module full_adder2(
    input a,
    input b,
    input cin,
    output reg sum, // always中的被赋值的变量必须为reg
    output reg cout
);

    // 敏感列表包含所有的信号
    always @(a or b or cin) // 当然，更直接的写法就是 always @(*)这里是因为神这么写
    begin
        // 和为异或
        sum = a ^ b ^ cin;
        // 进位为三位中的任意两位与再或
        cout = (a & b) | (a & cin) | (b & cin);
    end

endmodule

module full_adder3(
    input a,
    input b,
    input cin,
    output reg sum, // always中的被赋值的变量必须为reg
    output reg cout
);

    reg m1, m2, m3;

    // 敏感列表包含所有的信号
    always @(a or b or cin)
    begin
        // 和为异或
        sum = a ^ b ^ cin;
        // 进位为三位中的任意两位与再或
        // 加上中间变量
        m1 = a & b;
        m2 = a & cin;
        m3 = b & cin;
        cout = (m1 | m2) | m3;
    end

endmodule

module AddWithCarryInCarryOut #(
    parameter NUMBITS = 3 // 定义一个代表位数的参数
)(
    input [NUMBITS : 1] OpdA, // 3、2、1三位（神从1开始记数 | 哈哈哈笑死了
    input [NUMBITS : 1] OpdB,
    input CarryIn,
    output [NUMBITS : 1] Sum,
    output CarryOut
);

    // 直接用拼接操作计算
    assign {CarryOut, Sum} = OpdA + OpdB + CarryIn;

endmodule

module find_ones(
    input [7:0] x,
    output [2:0] y
);

    // 神用了二分法
    wire [3:0] data_4;
    wire [1:0] data_2;

    // 检查高4位，用"|"缩减或
    // 等效为assign y[2] = x[7] | x[6] | x[5] | x[4];
    assign y[2] = |x[7:4];
    // 如果高4位有1，则 data_4 选高4位；否则选低4位
    assign data_4 = y[2] ? x[7:4] : x[3:0];
    // 检查data_4的高2位，用"|"缩减或
    assign y[1] = |data_4[3:2];
    // 如果data_4的高2位有1，则 data_2 选高2位；否则选低2位
    assign data_2 = y[1] ? data_4[3:2] : data_4[1:0];
    // 检查data_2的高1位
    assign y[0] = data_2[1];

endmodule

module find_one(
    input [7:0] data,
    output [2:0] index
);

    // 神用了二分法
    wire [3:0] data_4;
    wire [1:0] data_2;

    // 检查低4位 data[3:0]
    // ~|data[3:0] (缩减或非)：当且仅当低4位全部为0时，结果为'1'
    // index[2] = 1 表示'1'在高4位
    assign index[2] = ~|data[3:0]; 
    // 如果 index[2] 为 1 (低4位全0)，则 data_4 选高4位
    assign data_4 = index[2] ? data[7:4] : data[3:0];

    // 检查 data_4 的低2位
    // index[1] = 1 表示 '1' 在 data_4 的高2位
    assign index[1] = ~|data_4[1:0];
    assign data_2 = index[1] ? data_4[3:2] : data_4[1:0];

    // 检查 data_2 的低1位
    // index[0] = 1 表示 '1' 在 data_2 的高1位
    assign index[0] = ~data_2[0];

endmodule

module left_shift_middle32(
    input [31:0] data,
    input [4:0] ctrl,
    output reg [31:0] out
);

    reg [31:0] temp;

    // 核心逻辑就是二进制数的分解，5bit刚好可以表达32位
    always@(data or ctrl)
    begin
        // 第0级：由 ctrl[0] 控制是否移1位
        temp = ctrl[0] ? {{data[30:0]}, 1'b0} : data;
        // 第1级：由 ctrl[1] 控制是否移2位
        temp = ctrl[1] ? {{temp[29:0]}, 2'b0} : temp;
        // 第2级：由 ctrl[2] 控制是否移4位
        temp = ctrl[2] ? {{temp[27:0]}, 4'b0} : temp;
        // 第3级：由 ctrl[3] 控制是否移8位
        temp = ctrl[3] ? {{temp[23:0]}, 8'b0} : temp;
        // 第4级：由 ctrl[4] 控制是否移16位
        temp = ctrl[4] ? {{temp[15:0]}, 16'b0} : temp;
        out = temp;
    end

endmodule

module block4(
    input clk,
    input d_in,
    output reg Q0,
    output reg Q1,
    output reg Q2,
    output reg Q3
);

    // 数据在时钟沿从 din -> Q0 -> Q1 -> Q2 -> Q3 移动
    always@(posedge clk)
    begin
        Q0 <= d_in; // 使用非阻塞赋值
        Q1 <= Q0;
        Q2 <= Q1;
        Q3 <= Q2;
    end

endmodule

module shifter32(
    input clk,
    input [32:0] a,
    output reg [32:0] c
);

    // 在每个时钟上升沿
    // 寄存器 c 会锁存 a 左移8位、低位补0的结果
    always @(posedge clk)
    begin
        c <= {a[23:0], 8'b0};
    end

endmodule

module counter1bit(
    input clk,
    input reset,
    input cin,
    output cout,
    output reg bit // 状态寄存器
);

    reg bitnext; // 下一状态

    // 时序逻辑部分 D触发器
    always @(posedge clk or negedge reset)
    begin
        if (!reset)
            bit <= 0;
        else
            bit <= bitnext;
    end

    // 组合逻辑部分，下一状态的逻辑
    always @(bit or cin)
    begin
        // bitnext = bit XOR cin (T触发器逻辑)
        // cin=1 时翻转, cin=0 时保持
        bitnext = bit ^ cin;
    end

    // 组合逻辑部分，进位输出
    always @(bit or cin)
    begin
        // cout = bit AND cin
        // 当本位为1且有进位时，向高位输出进位
        cout = bit & cin;
    end

endmodule

module timerTick(
    input clk,
    input reset,
    input preset,
    output reg [4:0] tick,
    output reg done
);

    always @(posedge clk or negedge reset)
    begin
        if (!reset) // 异步复位，最高优先级
        begin
            tick <= 5'b0;
            done <= 0;
        end else
        begin
            if (preset) // 同步预置
            begin
                tick <= 5'b0;
                done <= 0;
            end else
            begin // 正常计数逻辑
                if (tick < 16)
                begin
                    tick <= tick +1'b1;
                    done <= 0;
                end else
                begin
                    tick <= 5'b0;
                    done <= 1;
                end
            end
        end
    end

endmodule

module RegFileWithMemory #(
    parameter N = 2, // N=2, 地址位宽 (2 bits, 可寻址 2^2=4 个)
    parameter M = 2 // M=2, 数据位宽 (2 bits, 2 bits)
)(
    input Clk,
    input wire Readwrite,        // 1=读, 0=写
    input wire [N-1:0] Index,    // 寄存器地址
    input wire [M-1:0] DataIn,   // 写入的数据
    output reg [M-1:0] Dataout   // 读出的数据
);

    // 定义寄存器文件存储体 (内存)
    // 这是一个 M 位宽, 深度为 2^N 的数组
    // (N=2 => 2^2 = 4 个寄存器, 地址 0, 1, 2, 3)
    reg [M-1:0] RegFile [ (2**N)-1 : 0 ];

    always @(posedge Clk)
    begin
        if (Readwrite) // 读
        begin
            // 将 RegFile[Index] 的值锁存到 Dataout 寄存器
            Dataout <= RegFile[Index];
        end else // 写
        begin
            // 将 DataIn 写入指定地址
            RegFile[Index] <= DataIn;
        end
    end

endmodule

